// Build the lib_retry_envelope envelope per pgmq message. One per item.
// UUID v4 via Math.random — correlation_id is for tracing, not authentication,
// so cryptographic randomness isn't required (n8n sandbox blocks crypto).
function randomUUID() {
  const hex = '0123456789abcdef';
  let out = '';
  for (let i = 0; i < 32; i++) {
    let c;
    if (i === 12) c = '4';
    else if (i === 16) c = hex[8 + Math.floor(Math.random() * 4)];
    else c = hex[Math.floor(Math.random() * 16)];
    out += c;
    if (i === 7 || i === 11 || i === 15 || i === 19) out += '-';
  }
  return out;
}
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.msg_id) continue;
  out.push({ json: {
    queue_name: 'q_orders_normalize',
    msg_id: j.msg_id,
    attempt_count: j.read_ct ?? 1,
    processor_workflow_id: 'OdYCsotEru63kxN7',
    payload: j.message,
    correlation_id: randomUUID(),
    raw_payload_id: j.message?.raw_id ?? null,
  } });
}
return out;
